adcs_vec3_t sun_unit;
double axial, cross_track, px, py, pz, ux, uy, uz, normv;
unint32 phase;
int eclipse;

/* ---- latch FAULT: once in FAULT, stay in FAULT ---- */
if (ep_state.mode == EP_FAULT) {
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = ep_state.elapsed;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

/* ---- validity checks ---- */
{
    int bad = 0;
    if (ep_input.position_eci_m == 0 || ep_input.sun_direction_eci == 0) bad = 1;
    else if (!adcs_is_finite_vec3(ep_input.position_eci_m) ||
             !adcs_is_finite_vec3(ep_input.sun_direction_eci)) bad = 1;
    else if (ep_input.enable != 0 && ep_input.enable != 1) bad = 1;
    else if (!isfinite(ep_config.earth_radius_m) || ep_config.earth_radius_m <= 0.0) bad = 1;
    else if (ep_config.recovery_cycles < 1U || ep_config.recovery_cycles > 100U) bad = 1;
    else if (ep_config.warmup_cycles < 1U || ep_config.warmup_cycles > 100U) bad = 1;
    else if (!isfinite(ep_input.battery_soc) || ep_input.battery_soc < 0.0 ||
             ep_input.battery_soc > 1.0) bad = 1;
    else if (!isfinite(ep_config.payload_on_soc) || ep_config.payload_on_soc < 0.0 ||
             ep_config.payload_on_soc > 1.0) bad = 1;
    else if (!isfinite(ep_config.payload_off_soc) || ep_config.payload_off_soc < 0.0 ||
             ep_config.payload_off_soc > 1.0) bad = 1;
    else if (ep_config.payload_off_soc > ep_config.payload_on_soc) bad = 1;
    if (bad) {
        ep_state.mode = EP_FAULT;
        ep_state.elapsed = 0U;
        ep_output.mode = EP_FAULT;
        ep_output.elapsed = 0U;
        ep_output.payload_on = 0;
        ep_output.heater_on = 0;
        ep_output.axial_m = 0.0;
        ep_output.cross_track_m = 0.0;
        return;
    }
}

/* ---- normalize Sun direction using linked library ---- */
if (adcs_vec3_normalize(ep_input.sun_direction_eci, ADCS_EPS_NORM, &sun_unit) != ADCS_OK) {
    ep_state.mode = EP_FAULT;
    ep_state.elapsed = 0U;
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0U;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

px = ep_input.position_eci_m->x;
py = ep_input.position_eci_m->y;
pz = ep_input.position_eci_m->z;
ux = sun_unit.x;
uy = sun_unit.y;
uz = sun_unit.z;
axial = px * ux + py * uy + pz * uz;
{
    double rx = px - axial * ux;
    double ry = py - axial * uy;
    double rz = pz - axial * uz;
    cross_track = sqrt(rx * rx + ry * ry + rz * rz);
}
eclipse = (axial < 0.0) && (cross_track < ep_config.earth_radius_m);

/* ---- disabled ---- */
if (ep_input.enable == 0) {
    ep_state.mode = EP_SUN;
    ep_state.elapsed = 0U;
    ep_output.mode = EP_SUN;
    ep_output.elapsed = 0U;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = axial;
    ep_output.cross_track_m = cross_track;
    return;
}

/* ---- eclipse preempts every sunlight phase ---- */
if (eclipse) {
    ep_state.mode = EP_ECLIPSE;
    ep_state.elapsed = 0U;
    ep_output.mode = EP_ECLIPSE;
    ep_output.elapsed = 0U;
    ep_output.payload_on = 0;
    ep_output.heater_on = 1;
    ep_output.axial_m = axial;
    ep_output.cross_track_m = cross_track;
    return;
}

/* ---- sunlight phase machine ---- */
phase = (unint32)ep_state.mode;
switch (phase) {
    case EP_ECLIPSE:
        ep_state.mode = EP_RECOVERY;
        ep_state.elapsed = 1U;
        break;
    case EP_RECOVERY:
        ep_state.elapsed += 1U;
        if (ep_state.elapsed >= ep_config.recovery_cycles) {
            ep_state.mode = EP_WARMUP;
            ep_state.elapsed = 1U;
        }
        break;
    case EP_WARMUP:
        ep_state.elapsed += 1U;
        if (ep_state.elapsed >= ep_config.warmup_cycles) {
            if (ep_input.battery_soc >= ep_config.payload_on_soc) {
                ep_state.mode = EP_SUN;
                ep_state.elapsed = 0U;
            } else {
                ep_state.mode = EP_LOADWAIT;
                ep_state.elapsed = 0U;
            }
        }
        break;
    case EP_LOADWAIT:
        if (ep_input.battery_soc >= ep_config.payload_on_soc) {
            ep_state.mode = EP_SUN;
            ep_state.elapsed = 0U;
        }
        break;
    case EP_SUN:
        if (ep_input.battery_soc < ep_config.payload_off_soc) {
            ep_state.mode = EP_LOADSHED;
            ep_state.elapsed = 0U;
        }
        break;
    case EP_LOADSHED:
        if (ep_input.battery_soc >= ep_config.payload_on_soc) {
            ep_state.mode = EP_SUN;
            ep_state.elapsed = 0U;
        }
        break;
    default:
        ep_state.mode = EP_SUN;
        ep_state.elapsed = 0U;
        break;
}

ep_output.mode = ep_state.mode;
ep_output.elapsed = ep_state.elapsed;
ep_output.payload_on = (ep_state.mode == EP_SUN) ? 1 : 0;
ep_output.heater_on = 0;
ep_output.axial_m = axial;
ep_output.cross_track_m = cross_track;

