adcs_vec3_t sun_unit;
adcs_vec3_t pos;
adcs_vec3_t axial_component;
adcs_vec3_t perp_component;
double dot_axial;
double cross_track;
int faulted = 0;

if ((ep_input.enable != 0) && (ep_input.enable != 1)) {
    faulted = 1;
}
if ((ep_input.position_eci_m == NULL) || (ep_input.sun_direction_eci == NULL)) {
    faulted = 1;
}
if (!faulted) {
    if ((!adcs_is_finite_vec3(ep_input.position_eci_m)) ||
        (!adcs_is_finite_vec3(ep_input.sun_direction_eci))) {
        faulted = 1;
    }
}
if ((!isfinite(ep_config.earth_radius_m)) || (ep_config.earth_radius_m <= 0.0)) {
    faulted = 1;
}
if ((ep_config.recovery_cycles < 1U) || (ep_config.recovery_cycles > 100U) ||
    (ep_config.warmup_cycles < 1U) || (ep_config.warmup_cycles > 100U)) {
    faulted = 1;
}
if ((!isfinite(ep_input.battery_soc)) || (ep_input.battery_soc < 0.0) ||
    (ep_input.battery_soc > 1.0)) {
    faulted = 1;
}
if ((!isfinite(ep_config.payload_on_soc)) || (ep_config.payload_on_soc < 0.0) ||
    (ep_config.payload_on_soc > 1.0)) {
    faulted = 1;
}
if ((!isfinite(ep_config.payload_off_soc)) || (ep_config.payload_off_soc < 0.0) ||
    (ep_config.payload_off_soc > 1.0)) {
    faulted = 1;
}
if (ep_config.payload_off_soc > ep_config.payload_on_soc) {
    faulted = 1;
}
if (ep_state.mode == EP_FAULT) {
    faulted = 1;
}

if (faulted) {
    ep_state.mode = EP_FAULT;
    ep_state.elapsed = 0U;
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0U;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

if (adcs_vec3_normalize(ep_input.sun_direction_eci, ADCS_EPS_NORM, &sun_unit) != ADCS_OK) {
    ep_state.mode = EP_FAULT;
    ep_state.elapsed = 0U;
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0U;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;
    return;
}

pos = *ep_input.position_eci_m;
dot_axial = adcs_vec3_dot(&pos, &sun_unit);
axial_component = adcs_vec3_scale(&sun_unit, dot_axial);
perp_component = adcs_vec3_sub(&pos, &axial_component);
cross_track = adcs_vec3_norm(&perp_component);

ep_output.axial_m = dot_axial;
ep_output.cross_track_m = cross_track;

if (ep_input.enable == 0) {
    ep_state.mode = EP_SUN;
    ep_state.elapsed = 0U;
    ep_output.mode = EP_SUN;
    ep_output.elapsed = 0U;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    return;
}

if ((dot_axial < 0.0) && (cross_track < ep_config.earth_radius_m)) {
    ep_state.mode = EP_ECLIPSE;
    ep_state.elapsed = 0U;
    ep_output.mode = EP_ECLIPSE;
    ep_output.elapsed = 0U;
    ep_output.payload_on = 0;
    ep_output.heater_on = 1;
    return;
}

switch (ep_state.mode) {
case EP_ECLIPSE:
    ep_state.mode = EP_RECOVERY;
    ep_state.elapsed = 1U;
    ep_output.mode = EP_RECOVERY;
    ep_output.elapsed = 1U;
    ep_output.payload_on = 0;
    ep_output.heater_on = 1;
    return;

case EP_RECOVERY:
    ep_state.elapsed += 1U;
    if (ep_state.elapsed >= ep_config.recovery_cycles) {
        ep_state.mode = EP_WARMUP;
        ep_state.elapsed = 1U;
        ep_output.mode = EP_WARMUP;
        ep_output.elapsed = 1U;
        ep_output.payload_on = 0;
        ep_output.heater_on = 1;
    } else {
        ep_output.mode = EP_RECOVERY;
        ep_output.elapsed = ep_state.elapsed;
        ep_output.payload_on = 0;
        ep_output.heater_on = 1;
    }
    return;

case EP_WARMUP:
    ep_state.elapsed += 1U;
    if (ep_state.elapsed >= ep_config.warmup_cycles) {
        if (ep_input.battery_soc >= ep_config.payload_on_soc) {
            ep_state.mode = EP_SUN;
            ep_state.elapsed = 0U;
            ep_output.mode = EP_SUN;
            ep_output.elapsed = 0U;
            ep_output.payload_on = 1;
            ep_output.heater_on = 0;
        } else {
            ep_state.mode = EP_LOADWAIT;
            ep_state.elapsed = 0U;
            ep_output.mode = EP_LOADWAIT;
            ep_output.elapsed = 0U;
            ep_output.payload_on = 0;
            ep_output.heater_on = 0;
        }
    } else {
        ep_output.mode = EP_WARMUP;
        ep_output.elapsed = ep_state.elapsed;
        ep_output.payload_on = 0;
        ep_output.heater_on = 1;
    }
    return;

case EP_LOADWAIT:
    if (ep_input.battery_soc >= ep_config.payload_on_soc) {
        ep_state.mode = EP_SUN;
        ep_state.elapsed = 0U;
        ep_output.mode = EP_SUN;
        ep_output.elapsed = 0U;
